# hypothesis: A property defined on a metaclass is readable on the class but not on its instances, so checkers must reject instance access while CPython raises AttributeError.
from typing import TypeVar, reveal_type

T = TypeVar('T')


class Meta(type):
    @property
    def label(cls) -> str:
        return '<' + cls.__name__ + '>'

    def __call__(cls: type[T]) -> T:
        print('building', cls.__name__)
        return type.__call__(cls)


class Gadget(metaclass=Meta):
    def __init__(self) -> None:
        self.size = 1


def build(factory: type[T]) -> T:
    return factory()


def misuse(w: Gadget) -> str:
    return w.label  # expect-error: Gadget instances have no attribute 'label'


g = Gadget()
reveal_type(g)
reveal_type(Gadget.label)
print(Gadget.label)
h = build(Gadget)
reveal_type(h)
print('size', h.size)
try:
    print('misuse', misuse(g))
except AttributeError as e:
    print('AttributeError', type(e).__name__)
